// Simulated order database. In production this would be a Postgres or
// HTTP Request node querying your order service.
const ORDERS = {
  "ORD-1001": { orderId: "ORD-1001", customer: "A. Rivera", chargedOn: "2026-04-15", amount: 49.99, currency: "USD", duplicateOf: "ORD-1000", status: "settled" },
  "ORD-1002": { orderId: "ORD-1002", customer: "M. Chen", chargedOn: "2026-04-02", amount: 129.00, currency: "USD", duplicateOf: null, status: "settled" },
  "ORD-1003": { orderId: "ORD-1003", customer: "S. Okafor", chargedOn: "2026-03-27", amount: 18.50, currency: "USD", duplicateOf: null, status: "refunded" },
  // ORD-1004 comes back from the index but the billing join failed, so the
  // amount and currency are missing. The record is present and incomplete.
  "ORD-1004": { orderId: "ORD-1004", customer: "L. Duarte", chargedOn: "2026-04-11", amount: null, currency: null, duplicateOf: "ORD-1003", status: "settled" }
};

const body = $json.body || $json;
const orderId = body.orderId || "";
const message = body.message || "";

// The lookup returns an ARRAY. An unknown id returns an empty array, not an
// error. This lets the exercise demonstrate a successful execution with
// missing business data.
const orders = ORDERS[orderId] ? [ORDERS[orderId]] : [];

return [{
  json: {
    orderId,
    message,
    orders,
    orderCount: orders.length,
    // A lookup is only usable if a record came back AND the fields the agent
    // is about to reason over are actually populated.
    lookupComplete: orders.length > 0 && Number.isFinite(orders[0].amount) && orders[0].amount > 0 && typeof orders[0].currency === "string" && orders[0].currency.length === 3,
    orderBlock: orders.length ? JSON.stringify(orders[0], null, 2) : ""
  }
}];

